mapper.select:
SELECT * FROM ( SELECT DEAL_ID AS dealId, ORIGIN_URL AS originUrl, TITLE AS title, CURRENT_PRICE AS currentPrice, START_PRICE AS startPrice, MALL_NAME AS mallName, COMMUNITY_NAME AS communityName, LAST_UPDATE_DATE AS lastUpdateDate, IMAGE_URL AS imageUrl, ROW_NUMBER() OVER(ORDER BY LAST_UPDATE_DATE DESC) AS rNum FROM TB_HOTDEAL_TRACKER WHERE 1=1
AND TITLE LIKE '%' || #{keyword} || '%'
) /* rowStart 대신 pageStart + 1을 사용하고, rowEnd 대신 pageStart + perPageNum을 사용합니다 */ WHERE rNum BETWEEN (#{pageStart} + 1) AND (#{pageStart} + #{perPageNum})
